generator client {
  provider = "prisma-client"
  output   = "../generated/prisma"
}

datasource db {
  provider = "postgresql"
}

model Produk {
  id         Int      @id @default(autoincrement())
  nama       String   @unique
  harga      Int
  stok       Int      @default(0)
  dibuatPada DateTime @default(now())
}
